const CACHE='danchu-first-chapter-081';
const ASSETS=['./view-gestures.js?v=081','./entry.js?v=081','./first-room.js?v=081','./first-room-engine.js?v=081','./first-room-renderer.js?v=081','./first-room.css?v=081','./scene-surface.js?v=081','./interaction-motion.js?v=081','./travel-art/first-pillow-v8.webp?v=081','./travel-art/first-props-v8.webp?v=081','./polish.css?v=070','./interaction-motion.js?v=070','./scene-surface.js?v=070','./play.js?v=070','./play-engine.js?v=070','./world.js?v=070','./adventure.js?v=070','./style.css?v=070','./travel-art/seoul-drawer-v7.webp?v=070','./travel-art/drawer-interior-v7.webp','./travel-art/travel-props-empty-v5.webp','./scene-surface.js','./travel-art/seoul-clean-v3.webp','./travel-art/seoul-diffuse-v4.webp','./travel-art/seoul-pillow-v3.webp','./travel-art/travel-props-v3.webp','./','./index.html','./style.css','./play.js','./play-engine.js','./world.js','./adventure.js','./manifest.webmanifest','./icon.svg','./travel-art/seoul.webp','./travel-art/tokyo.webp','./travel-art/taipei.webp','./travel-art/bangkok.webp','./travel-art/paris.webp','./travel-art/lisbon.webp','./travel-art/tools.webp','./travel-art/discoveries.webp','./travel-art/seoul-searched.webp','./travel-art/tokyo-searched.webp','./travel-art/taipei-searched.webp','./travel-art/bangkok-searched.webp','./travel-art/paris-searched.webp','./travel-art/lisbon-searched.webp'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>(k.startsWith('strange-cafe-')||k.startsWith('button-')||k.startsWith('danchu-case-')||k.startsWith('danchu-adventure-')||k.startsWith('danchu-travel-')||k.startsWith('danchu-first-chapter-'))&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request,{cache:'no-store'}).then(r=>{if(r.ok){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
